                    ->transform.position -
                ((PathAttachmentSample *)((char *)path->primary_samples + delta_offset))
                    ->transform.position;
            ((PathAttachmentSample *)((char *)path->primary_samples + delta_offset))
                ->delta_length =
                ((PathAttachmentSample *)((char *)path->primary_samples + delta_offset))
                    ->delta_dir_to_next.Normalize();

            ((PathAttachmentSample *)((char *)path->secondary_samples + delta_offset))
                ->delta_dir_to_next =
                ((PathAttachmentSample *)((char *)path->secondary_samples +
                                          delta_offset) +
                 1)
                    ->transform.position -
                ((PathAttachmentSample *)((char *)path->secondary_samples +
                                          delta_offset))
