        ((PathTemplateSample *)((char *)secondary_samples + lead_offset))
            ->transform.position.y = 0.49000001f;
        ((PathTemplateSample *)((char *)secondary_samples + lead_offset))
            ->transform.position.z = z;
        ((PathTemplateSample *)((char *)secondary_samples + lead_offset))
            ->delta_length = 1.0f;
    }

