        int z_index = local_index + 1;
        ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.position.x = 0.0f;
        ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.position.z = (float)z_index;
        ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.position.y = 0.0f;

        float basis_y = Cos(Sin(turn_phase * 3.0f) * 0.30000001f);
