        ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.basis_forward =
            ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.position -
            ((PathTemplateSample *)((char *)primary_samples + sample_offset))[-1].transform.position;
        ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.basis_forward.Normalize();
        ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.basis_right.Cross(
            ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.basis_up,
            ((PathTemplateSample *)((char *)primary_samples + sample_offset))[0].transform.basis_forward);

        copy_wibble_frame(primary_samples, secondary_samples, sample_offset);
        ++local_index;
        sample_offset += sizeof(PathTemplateSample);
    } while (sample_offset < 31 * (int)sizeof(PathTemplateSample));

    compute_path_deltas(this);
